def sample_mean(numbers: List[float]) -> float:
    """For a given list of input numbers calculate sample mean"""
    return sum(numbers) / len(numbers)

def population_standard_deviation(numbers: List[float]) -> float:
    """For a given list of input numbers calculate Population Standard Deviation"""
    mean = sample_mean(numbers)
    dev = 0
    for number in numbers:
        dev += (number - mean) ** 2
    return (dev / len(numbers)) ** 0.5

