    """You are given a string that may or may not contain nested parentheses and spaces. Your goal is to check
    if all the parentheses in this string are balanced (every open parentheses has a corresponding closing one,
    and their order is correct).
    >>> check_paren('(()())')
    True
    >>> check_paren('(()(()((()))))((())))')
    True
    >>> check_paren('(()(((()((())'
    False
    """
    stack = []
    for char in string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if len(stack) > 0:
                stack.pop()
            else:
                return False
    return len(stack) == 0


